import{_ as d,C as l,c as p,o as m,aa as r,j as e,G as t,w as o}from"./chunks/framework.Cn7WEiMX.js";const u="data:image/png;base64,",g="/assets/open-output-log.CHswztjf.png",f="/assets/settings-enable-console.DKk5bfd1.png",b="/assets/notepad-yaml.Dy-27V9j.png",k="/assets/vscode-yaml-highlighting.O-nWg-CZ.png",I=JSON.parse('{"title":"配置开发简介","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"Terra","link":"/wiki/Terra"},{"title":"config-packs","link":"/wiki/Terra/config-packs"},{"title":"config-development","link":"/wiki/Terra/config-packs/config-development"},{"title":"配置开发简介","link":"/wiki/Terra/config-packs/config-development/config-development-introduction"}]},"headers":[],"relativePath":"wiki/Terra/config-packs/config-development/config-development-introduction.md","filePath":"wiki/Terra/config-packs/config-development/config-development-introduction.md"}'),A={name:"wiki/Terra/config-packs/config-development/config-development-introduction.md"},h={class:"details custom-block"};function C(T,a,_,v,q,P){const i=l("tab"),n=l("tabs"),s=l("NolebaseGitContributors"),c=l("NolebaseGitChangelog");return m(),p("div",null,[a[6]||(a[6]=r('<h1 id="配置开发简介" tabindex="-1">配置开发简介 <a class="header-anchor" href="#配置开发简介" aria-label="Permalink to &quot;配置开发简介&quot;">​</a></h1><p>本章节将会大致讲述相关信息，包括在着手开发地形包之前的基础安装步骤。</p><h2 id="_1-安装测试环境" tabindex="-1">1. 安装测试环境 <a class="header-anchor" href="#_1-安装测试环境" aria-label="Permalink to &quot;1. 安装测试环境&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">警告</p><p>不要在生产环境下部署本教程提及的任何内容。</p></div><p>在着手制作新地形包之前，你将会需要合适的测试用服务器或客户端。我们推荐使用 <a href="https://fabricmc.net/" target="_blank" rel="noreferrer">Fabric</a> 客户端，但最终这都取决于你。你可以参考<a href="./../../getting-started/">初次使用</a>章节了解如何下载与安装 Terra。</p><h3 id="打开控制台" tabindex="-1">打开控制台 <a class="header-anchor" href="#打开控制台" aria-label="Permalink to &quot;打开控制台&quot;">​</a></h3><p>在对应平台上运行 Terra 之后，你必须确保你能够打开控制台。这会因你使用的加载器类型而略有不同。我们不会展开讲述如何找到所有平台的控制台，这不属于教程范围。</p><details class="details custom-block"><summary>官方 Minecraft 启动器</summary><ol><li>打开启动器，在左下角找到这个按钮，进入“设置”界面：</li></ol><figure><img src="'+u+'" alt="" tabindex="0"><figcaption></figcaption></figure><ol start="2"><li>在这里打开“启动后显示日志”选项：</li></ol><figure><img src="'+g+'" alt="" tabindex="0"><figcaption></figcaption></figure><p>这样，在启动 Minecraft 之后就会出现控制台日志。</p></details><details class="details custom-block"><summary>MultiMC 启动器</summary><ol><li><p>打开 MultiMC 启动器的设置界面。</p></li><li><p>打开“启动时显示日志”选项：</p></li></ol><figure><img src="'+f+'" alt="" tabindex="0"><figcaption></figcaption></figure><p>这样，在启动 Minecraft 之后就会出现控制台日志。</p></details><h3 id="选择编辑器" tabindex="-1">选择编辑器 <a class="header-anchor" href="#选择编辑器" aria-label="Permalink to &quot;选择编辑器&quot;">​</a></h3><p>在开发地形包时，你会经常用到编辑器，所以选择一个合适的编辑器至关重要。你可以使用任何你想要的编辑器，但我们<em>非常</em>推荐你选择下面这些：</p>',11)),e("details",h,[a[2]||(a[2]=e("summary",null,"语法高亮",-1)),a[3]||(a[3]=e("p",null,"如果编辑器有语法高亮功能，这可以让理解与配置编写变得更加简单，它们的结构会更易于分辨。下面这两张图更能描述这一优势：",-1)),t(n,null,{default:o(()=>[t(i,{name:"无语法高亮"},{default:o(()=>[...a[0]||(a[0]=[e("figure",null,[e("img",{src:b,alt:"",tabindex:"0"}),e("figcaption")],-1)])]),_:1}),t(i,{name:"有语法高亮"},{default:o(()=>[...a[1]||(a[1]=[e("figure",null,[e("img",{src:k,alt:"",tabindex:"0"}),e("figcaption")],-1)])]),_:1})]),_:1})]),a[7]||(a[7]=r('<details class="details custom-block"><summary>内置的文件浏览器</summary><p>通过文本编辑器将一整个文件夹以工程文件打开，会比只打开一个文件要更加高效与专业。在配置之间快速切换，一眼即可浏览文件结构，以及在编辑器中管理文件夹可以大幅度提升编写体验与效率。这可以节省许多时间，而无需在编辑器旁开着其他文件管理器。</p></details><h4 id="推荐的编辑器" tabindex="-1">推荐的编辑器 <a class="header-anchor" href="#推荐的编辑器" aria-label="Permalink to &quot;推荐的编辑器&quot;">​</a></h4><ul><li><a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">VSCode</a> &gt;</li><li><a href="https://www.jetbrains.com/idea/download/" target="_blank" rel="noreferrer">IntelliJ IDEA 社区版</a> &gt;</li></ul><h2 id="_2-找到-terra-文件夹" tabindex="-1">2. 找到 Terra 文件夹 <a class="header-anchor" href="#_2-找到-terra-文件夹" aria-label="Permalink to &quot;2. 找到 Terra 文件夹&quot;">​</a></h2><p>你需要知道 Terra 文件夹所在路径，这对日后的地形包开发至关重要：</p>',5)),t(n,null,{default:o(()=>[t(i,{name:"Fabric"},{default:o(()=>[...a[4]||(a[4]=[e("p",null,[e("code",null,"/config/Terra/")],-1)])]),_:1}),t(i,{name:"Bukkit"},{default:o(()=>[...a[5]||(a[5]=[e("p",null,[e("code",null,"/plugins/Terra/")],-1)])]),_:1})]),_:1}),a[8]||(a[8]=r('<h3 id="子文件夹" tabindex="-1">子文件夹 <a class="header-anchor" href="#子文件夹" aria-label="Permalink to &quot;子文件夹&quot;">​</a></h3><p>其中有两个子文件夹你必须了解：</p><div class="info custom-block"><p class="custom-block-title"><code>Terra/packs</code></p><p>包含所有安装的地形包。默认情况下，Terra 会预置一些带配置的地形包，就在这个文件夹下的 <code>default.zip</code> 中。</p></div><div class="info custom-block"><p class="custom-block-title"><code>Terra/addons</code></p><p>包含所有安装的拓展。与默认地形包相似，Terra 也在这里预置了一系列<em>核心拓展</em>，这在本文开头有所提及。</p></div><h2 id="_3-开发流程" tabindex="-1">3. 开发流程 <a class="header-anchor" href="#_3-开发流程" aria-label="Permalink to &quot;3. 开发流程&quot;">​</a></h2><h3 id="从文件夹导入" tabindex="-1">从文件夹导入 <a class="header-anchor" href="#从文件夹导入" aria-label="Permalink to &quot;从文件夹导入&quot;">​</a></h3><p>在 <code>Terra/packs</code> 内的地形包可以直接载入。若需要频繁改动，无需将其打包。你可以直接将配置文件放在地形包文件夹中，Terra 照样会读取。</p><h3 id="重载" tabindex="-1">重载 <a class="header-anchor" href="#重载" aria-label="Permalink to &quot;重载&quot;">​</a></h3><p>改动地形包后无需删除并重生成世界，你做出的任何改动都可以通过 <code>/packs reload</code> 命令实时预览。如果地形包没有报错，当前世界新生成的区块会立即反映出改动（前提是你仍然使用当前生成器生成新区块）。</p><h4 id="改动预览" tabindex="-1">改动预览 <a class="header-anchor" href="#改动预览" aria-label="Permalink to &quot;改动预览&quot;">​</a></h4><p>重载后，你需要重新生成区块来预览改动。比较快捷的一种方式是输入命令 <code>/tp ~ ~ ~1000</code>，这会让你在正 Z 轴上移动一千格，足以让你在传送后被新的区块围绕。需要注意的是，你应该在地形包载入<em>完毕</em>后执行这条命令。</p><p>朝一个方向飞行也是一种可行的选择，这样就不会碰到旧区块（误以为改动没有生效）。</p><p>如果你在 Fabric 客户端上进行开发，你也可以使用 WorldEdit 的 <code>//regen</code> 命令重新生成指定区域的地形（如果不需要前后对比，则这个方法可能稍慢于直接传送）。截止本章节撰写完毕前，<code>//regen</code> 命令在安装了 Terra 6.4.3 的 Bukkit 服务端上似乎并无效果。</p><h2 id="_4-着手开发地形包" tabindex="-1">4. 着手开发地形包 <a class="header-anchor" href="#_4-着手开发地形包" aria-label="Permalink to &quot;4. 着手开发地形包&quot;">​</a></h2><p>在这之后，你有两个选项。既可以从零开始，也可以着手修改现有的地形包。</p><div class="info custom-block"><p class="custom-block-title"><a href="./creating-a-pack-from-scratch/">从零开始制作地形包</a> &gt;</p><p>从零开始制作地形包可以帮助你了解许多内容。你将会了解从配置到世界生成之间器的知识。如果你想要做些非常独特的东西，或是为了服务器及个人项目，抑或只是想了解世界生成器的工作原理，我们都推荐你跟随这一部分教程。</p></div><div class="info custom-block"><p class="custom-block-title"><a href="./modifying-an-existing-pack.html">修改现有地形包</a> &gt;</p><p>修改现有地形包对你来讲相对轻松，因为大部分繁杂的任务都已经完成。如果你只是想要微调一些细节，那么这就是最适合你的。这部分章节不会像“从零开始”那样为你彻底讲解，所以如果你对修改有什么不了解的地方，我们推荐你一并阅读上述章节中的内容。</p></div>',17)),t(s),t(c)])}const V=d(A,[["render",C]]);export{I as __pageData,V as default};
